// Generated from src/registry/sources/control-ui/recipes/scroll-area.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const scrollAreaKnobs = [
  "--cui-scroll-area-thumb-radius",
  "--cui-scroll-area-thumb-background",
  "--cui-scroll-area-corner-background",
] as const;
export type ScrollAreaKnobStyle = Partial<Record<(typeof scrollAreaKnobs)[number], string>>;

@layer components {
  :where([data-control-family="scroll-area"][data-slot="root"]) {
    --cui-scroll-area-thumb-radius: 9999px;
    --cui-scroll-area-thumb-background: oklch(from var(--foreground) l c h / 0.4);
    --cui-scroll-area-corner-background: transparent;
  }

  @supports (corner-shape: squircle) {
    @container not style(--corner-shape: round) {
      :where([data-control-family="scroll-area"][data-slot="root"] > [data-control-family="progressive-blur"]) {
        display: none;
      }
    }
  }

  :where([data-control-family="scroll-area"][data-slot="root"] > [data-scroll-area-viewport]) {
    position: relative;
    z-index: 0;
    border-radius: inherit;
    outline: none;
    transition:
      --_scroll-area-fade-top var(--duration-fast) var(--ease-standard),
      --_scroll-area-fade-bottom var(--duration-fast) var(--ease-standard),
      --_scroll-area-fade-left var(--duration-fast) var(--ease-standard),
      --_scroll-area-fade-right var(--duration-fast) var(--ease-standard);
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-mask]:is(
        [data-overflow-x-start],
        [data-overflow-x-end],
        [data-overflow-y-start],
        [data-overflow-y-end]
      )
      > [data-scroll-area-viewport]
  ) {
    mask-image:
      linear-gradient(
        to bottom,
        oklch(0 0 0 / 0),
        oklch(0 0 0) min(50%, var(--_scroll-area-fade-top)),
        oklch(0 0 0) calc(100% - min(50%, var(--_scroll-area-fade-bottom))),
        oklch(0 0 0 / 0)
      ),
      linear-gradient(
        to right,
        oklch(0 0 0 / 0),
        oklch(0 0 0) min(50%, var(--_scroll-area-fade-left)),
        oklch(0 0 0) calc(100% - min(50%, var(--_scroll-area-fade-right))),
        oklch(0 0 0 / 0)
      );
    mask-composite: intersect;
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-y-start]:not([data-lock-axis="y"], [data-lock-axis="both"])
      > [data-scroll-area-viewport]
  ) {
    --_scroll-area-fade-top: var(--scroll-fade-size);
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-y-end]:not([data-lock-axis="y"], [data-lock-axis="both"])
      > [data-scroll-area-viewport]
  ) {
    --_scroll-area-fade-bottom: var(--scroll-fade-size);
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-x-start]:not([data-lock-axis="x"], [data-lock-axis="both"]):dir(ltr)
      > [data-scroll-area-viewport]
  ),
  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-x-end]:not([data-lock-axis="x"], [data-lock-axis="both"]):dir(rtl)
      > [data-scroll-area-viewport]
  ) {
    --_scroll-area-fade-left: var(--scroll-fade-size);
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-x-end]:not([data-lock-axis="x"], [data-lock-axis="both"]):dir(ltr)
      > [data-scroll-area-viewport]
  ),
  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-x-start]:not([data-lock-axis="x"], [data-lock-axis="both"]):dir(rtl)
      > [data-scroll-area-viewport]
  ) {
    --_scroll-area-fade-right: var(--scroll-fade-size);
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-y-start] > [data-control-family="progressive-blur"][data-side="top"]
  ),
  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-y-end]
      > [data-control-family="progressive-blur"][data-side="bottom"]
  ),
  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-x-start]
      > [data-control-family="progressive-blur"][data-side="inline-start"]
  ),
  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-overflow-x-end]
      > [data-control-family="progressive-blur"][data-side="inline-end"]
  ) {
    --_progressive-blur-visibility: visible;
    --_progressive-blur-enter: 1;
  }

  @media (prefers-reduced-transparency: reduce), (forced-colors: active) {
    :where([data-control-family="scroll-area"][data-slot="root"][data-mask] > [data-scroll-area-viewport]) {
      mask-image: none;
    }
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"][data-mask] > [data-scroll-area-viewport]:is(:focus-visible, :has(:focus-visible))
  ) {
    mask-image: none;
  }

  :where(
    [data-control-family="scroll-area"][data-slot="root"]
      > [data-scroll-area-viewport]:is(:focus-visible, :has(:focus-visible))
      ~ [data-control-family="progressive-blur"]
  ) {
    --_progressive-blur-visibility: hidden;
    --_progressive-blur-enter: 0;
  }

  :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-orientation="vertical"]) {
    inline-size: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-orientation="horizontal"]) {
    block-size: calc(var(--spacing) * 1.5);
  }

  :where([data-control-family="scroll-area"][data-slot="scrollbar"]) {
    z-index: 1;
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-visibility="always"]),
  :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-visibility="hover"]:is([data-hovering], [data-scrolling])),
  :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-visibility="scroll"][data-scrolling]) {
    opacity: 1;
  }

  :where([data-control-family="scroll-area"][data-slot="thumb"]) {
    border-radius: var(--cui-scroll-area-thumb-radius);
    background: var(--cui-scroll-area-thumb-background);
    transition: background-color var(--duration-fast) var(--ease-standard);
  }

  :where([data-control-family="scroll-area"][data-slot="corner"]) {
    background: var(--cui-scroll-area-corner-background);
  }
}

@property --_scroll-area-fade-top {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}

@property --_scroll-area-fade-bottom {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}

@property --_scroll-area-fade-left {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}

@property --_scroll-area-fade-right {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
}

@property --cui-scroll-area-thumb-radius {
  syntax: "<length-percentage>";
  inherits: true;
  initial-value: 0px;
}

@property --cui-scroll-area-thumb-background {
  syntax: "*";
  inherits: true;
  initial-value: transparent;
}

@property --cui-scroll-area-corner-background {
  syntax: "<color>";
  inherits: true;
  initial-value: transparent;
}

"use client";

import { ScrollArea as ScrollAreaPrimitive } from "@base-ui/react/scroll-area";
import type { ComponentProps, CSSProperties, Ref } from "react";
import type { ScrollAreaKnobStyle } from "@/components/control-ui/knob-contracts/scroll-area-knobs";
import { cn } from "@/components/control-ui/lib/cn";
import { useSkin } from "@/components/control-ui/skin-provider";
import { ProgressiveBlur, type ProgressiveBlurProps } from "@/components/control-ui/ui/progressive-blur";

export const scrollAreaScrollbarVisibilities = ["scroll", "hover", "always"] as const;

export type ScrollAreaScrollbarVisibility = (typeof scrollAreaScrollbarVisibilities)[number];

export type ScrollAreaLockAxis = "x" | "y" | "both";

export type ScrollAreaViewportProps = Omit<ComponentProps<"div">, "children" | "className" | "ref"> & {
  "data-control-ui"?: string;
  "data-control-family"?: string;
  "data-slot"?: string;
};

export type ScrollAreaProps = Omit<ComponentProps<"div">, "style"> & { style?: CSSProperties & ScrollAreaKnobStyle } & {
  viewportClassName?: string;
  viewportProps?: ScrollAreaViewportProps;
  viewportRef?: Ref<HTMLDivElement>;
  maxHeight?: string;
  mask?: boolean;
  blur?: boolean;
  blurProps?: Pick<ProgressiveBlurProps, "style">;
  lockAxis?: ScrollAreaLockAxis;
  scrollbarVisibility?: ScrollAreaScrollbarVisibility;
};

function Scrollbar({
  orientation,
  visibility,
  thumbStyle,
}: {
  orientation: "vertical" | "horizontal";
  visibility: ScrollAreaProps["scrollbarVisibility"];
  thumbStyle?: CSSProperties & ScrollAreaKnobStyle;
}) {
  return (
    <ScrollAreaPrimitive.Scrollbar
      orientation={orientation}
      data-control-ui="scroll-area"
      data-control-family="scroll-area"
      data-slot="scrollbar"
      data-visibility={visibility}
      className={cn("m-px flex touch-none select-none", orientation === "vertical" ? "justify-center" : "flex-col")}
    >
      <ScrollAreaPrimitive.Thumb
        data-control-ui="scroll-area"
        data-control-family="scroll-area"
        data-slot="thumb"
        className={cn("flex-1", orientation === "vertical" ? "w-full" : "h-full")}
        style={thumbStyle}
      />
    </ScrollAreaPrimitive.Scrollbar>
  );
}

function viewportStyle(maxHeight: ScrollAreaProps["maxHeight"], lockX: boolean, lockY: boolean): CSSProperties | undefined {
  if (!maxHeight && !lockX && !lockY) return undefined;
  return {
    ...(maxHeight ? { maxHeight } : {}),
    ...(lockX ? { overflowX: "hidden" } : {}),
    ...(lockY ? { overflowY: "hidden" } : {}),
  };
}

export function ScrollArea({
  className,
  viewportClassName,
  viewportProps,
  viewportRef,
  maxHeight,
  mask = true,
  blur,
  blurProps,
  lockAxis,
  scrollbarVisibility = "scroll",
  children,
  style,
  ...props
}: ScrollAreaProps) {
  const skin = useSkin();
  const resolvedBlur = blur ?? skin.scrollAreaBlur ?? false;
  const lockX = lockAxis === "x" || lockAxis === "both";
  const lockY = lockAxis === "y" || lockAxis === "both";
  const resolvedViewportStyle = viewportStyle(maxHeight, lockX, lockY);
  const { style: viewportPropsStyle, ...resolvedViewportProps } = viewportProps ?? {};
  const mergedViewportStyle = viewportPropsStyle || resolvedViewportStyle ? { ...viewportPropsStyle, ...resolvedViewportStyle } : undefined;
  const thumbStyle = style;
  const cornerStyle = style;

  return (
    <ScrollAreaPrimitive.Root
      {...props}
      data-control-ui="scroll-area"
      data-control-family="scroll-area"
      data-slot="root"
      data-mask={mask || undefined}
      data-blur={resolvedBlur || undefined}
      data-lock-axis={lockAxis}
      className={cn("relative overflow-hidden", className)}
      style={style}
    >
      <ScrollAreaPrimitive.Viewport
        data-control-ui="scroll-area"
        data-control-family="scroll-area"
        data-slot="viewport"
        {...resolvedViewportProps}
        data-scroll-area-viewport=""
        ref={viewportRef}
        className={cn("h-full w-full", viewportClassName)}
        style={mergedViewportStyle}
      >
        <ScrollAreaPrimitive.Content
          data-control-ui="scroll-area"
          data-control-family="scroll-area"
          data-slot="content"
          style={{ minWidth: 0 }}
        >
          {children}
        </ScrollAreaPrimitive.Content>
      </ScrollAreaPrimitive.Viewport>
      {resolvedBlur && !lockY && <ProgressiveBlur {...blurProps} side="top" visible={false} />}
      {resolvedBlur && !lockY && <ProgressiveBlur {...blurProps} side="bottom" visible={false} />}
      {resolvedBlur && !lockX && <ProgressiveBlur {...blurProps} side="inline-start" visible={false} />}
      {resolvedBlur && !lockX && <ProgressiveBlur {...blurProps} side="inline-end" visible={false} />}
      {!lockY && <Scrollbar orientation="vertical" visibility={scrollbarVisibility} thumbStyle={thumbStyle} />}
      {!lockX && <Scrollbar orientation="horizontal" visibility={scrollbarVisibility} thumbStyle={thumbStyle} />}
      {!lockX && !lockY && (
        <ScrollAreaPrimitive.Corner
          data-control-ui="scroll-area"
          data-control-family="scroll-area"
          data-slot="corner"
          style={cornerStyle}
        />
      )}
    </ScrollAreaPrimitive.Root>
  );
}
